"""Unexecuted P1 acceptance code. Only synthetic readers, generated bytes, tmp_path."""
from io import BytesIO
from threading import Event
import json
import pytest
from PIL import Image
from pixivvault_nicegui.managed_novel_jobs import PinnedNovelSource, NovelJobIntent, ManagedNovelJobs
from pixivvault_nicegui.novel_storage import NovelExportStore, NovelStorageError
from pixivvault_nicegui.media_parity_policy import NovelDocument
