from pixivvault_nicegui.bootstrap import parse_args


class Reader:
    def __init__(self, series=False, fail=False):
        self.series, self.fail, self.closed = series, fail, False
        self.requests = []
    def require_identity(self): return '91'
    def close(self): self.closed = True
    def get_novel_payload(self, wid, aid):
        self.requests.append(('body', wid, aid))
        return dict(id=wid, userId=aid, userName='作者', title='題名'+wid,
                    content='[[rb:漢字 > かんじ]][newpage][uploadedimage:1]',
                    seriesNavData={'seriesId':'9'} if self.series else None,
                    textEmbeddedImages={'1':{'urls':{'original':'https://i.pximg.net/fixture.png'}}},
                    coverUrl='https://i.pximg.net/cover.png')
    def get_image_bytes(self, url):
        self.requests.append(('image', url))
        if self.fail:
            self.fail = False
            raise OSError('synthetic once')
        out = BytesIO()
        Image.new('RGB', (2, 2), 'blue').save(out, format='PNG')
        return out.getvalue()


def wait(owner, jid, state):
    with owner.jobs._condition:
        assert owner.jobs._condition.wait_for(lambda: any(j.job_id == jid and j.state == state for j in owner.jobs.snapshot()), 15)
    return next(j for j in owner.jobs.snapshot() if j.job_id == jid)


@pytest.mark.parametrize('fmt', ['TXT','EPUB','BOTH'])
@pytest.mark.parametrize('series', [False, True])
def test_selection_queue_bundle_library_restart(tmp_path, fmt, series):
    root = tmp_path / 'novels'
    reader = Reader(series)
    services = ApplicationServices(1, novel_fixture_root=root, novel_fixture_source=PinnedNovelSource(reader, {}))
    try:
        presentation = NovelSavePresentation(services)
        presentation.select('123', '91')
        selection = presentation.preview('123', fmt, ('123','124') if series else (), '連作' if series else None)
        assert services.jobs.snapshot() == ()
        job = presentation.enqueue(selection, 'operation')
        wait(services.novel_jobs, job.job_id, 'done')
        entry = presentation.library()[0]
        assert '漢字《かんじ》' in presentation.read_saved(entry)
        assert presentation.read_images(entry)
        saved = entry.saved
        assert saved.metadata['chapters'] == (['123','124'] if series else ['123'])
        receipt = json.loads((root/'exports'/saved.relative_receipt).read_bytes())
        assert receipt['schema'] == 2
    finally:
        services.close()
    fresh = Reader(series)
    services = ApplicationServices(1, novel_fixture_root=root, novel_fixture_source=PinnedNovelSource(fresh, {}))
    try:
        presentation = NovelSavePresentation(services)
        entry = presentation.library()[0]
        assert entry.saved == saved
        assert '漢字《かんじ》' in presentation.read_saved(entry)
        assert fresh.requests == []
    finally:
        services.close()


def test_failed_asset_retry_retains_operation_and_attempt(tmp_path):
    owner = ManagedNovelJobs(tmp_path/'jobs', PinnedNovelSource(Reader(fail=True), {'123':'91'}))
    try:
        job = owner.enqueue(NovelJobIntent('123','91','BOTH'), 'same-operation')
        failed = wait(owner, job.job_id, 'error')
        assert owner.saved_entries() == ()
        assert owner.jobs.control(job.job_id, 'retry', expected_revision=failed.revision)
        assert wait(owner, job.job_id, 'done').attempt == 2
        assert owner.jobs.operation_ids(job.job_id) == ('same-operation',)
    finally:
        owner.close()


def test_v1_and_v2_coexist_without_rewriting_old_receipt(tmp_path):
    store = NovelExportStore(tmp_path/'exports')
    doc = NovelDocument('123','91','題名','本文',None)
    old = store.save(doc, author_name='作者')
    old_bytes = (store.root/old.relative_receipt).read_bytes()
    bundle = render_practical_bundle([doc], author_name='作者', output_format='BOTH')
    new = store.save(doc, author_name='作者', output_format='BOTH', bundle=bundle,
                     metadata=dict(title='題名',author='作者',chapters=['123'],series_id=None))
    assert store.reconcile(old.relative_receipt, expected_sha256=old.receipt_sha256).saved == old
    assert store.reconcile(new.relative_receipt, expected_sha256=new.receipt_sha256).saved == new
    assert (store.root/old.relative_receipt).read_bytes() == old_bytes
    folder = (store.root/new.relative_receipt).parent
    (folder/'題名(123).txt').write_bytes(b'corrupt')
    with pytest.raises(NovelStorageError):
        store.reconcile(new.relative_receipt, expected_sha256=new.receipt_sha256)


def test_cli_requires_isolated_root_and_cookie(tmp_path):
    with pytest.raises(SystemExit):
        parse_args(['--novel-download-root',str(tmp_path/'novels')])
    config = parse_args(['--novel-download-root',str(tmp_path/'novels'),
                         '--pixiv-cookie-file',str(tmp_path/'credentials'/'cookie.txt')])
    assert config.novel_download_root == tmp_path/'novels'
    assert not (tmp_path/'novels').exists()
@pytest.mark.parametrize('unsafe', ['../escape.txt','images/../x.png','/tmp/x.txt','C:\\x.txt','images/CON.png'])
def test_bundle_rejects_unsafe_names_before_creating_generation(tmp_path, unsafe):
    store = NovelExportStore(tmp_path/'exports')
    doc = NovelDocument('123','91','題名','本文',None)
    with pytest.raises(NovelStorageError):
        store.save(doc, author_name='作者', output_format='TXT', bundle={unsafe:b'x'},
                   metadata=dict(title='題名',author='作者',chapters=['123'],series_id=None))
    assert list((store.root/'outputs').iterdir()) == []
    assert list((store.root/'.staging').iterdir()) == []


def test_stop_during_asset_fetch_never_publishes(tmp_path):
    entered, release = Event(), Event()
    class Slow(Reader):
        def get_image_bytes(self, url):
            entered.set()
            assert release.wait(10)
            return super().get_image_bytes(url)
    owner = ManagedNovelJobs(tmp_path/'jobs', PinnedNovelSource(Slow(), {'123':'91'}))
    try:
        job = owner.enqueue(NovelJobIntent('123','91','BOTH'), 'stop-operation')
        assert entered.wait(10)
        state = next(j for j in owner.jobs.snapshot() if j.job_id == job.job_id)
        assert owner.jobs.control(job.job_id, 'stop', expected_control_revision=state.control_revision)
        release.set()
        wait(owner, job.job_id, 'stopped')
        assert owner.saved_entries() == ()
        assert list((owner.store.root/'outputs').iterdir()) == []
    finally:
        release.set()
        owner.close()
@pytest.mark.parametrize('series', [False, True])
def test_bundle_multiple_targets_order_cas_uncertain_and_restart(tmp_path, monkeypatch, series):
    from dataclasses import replace
    from pixivvault_nicegui import novel_storage
    from pixivvault_nicegui.managed_novel_jobs import ManagedNovelError
    root = tmp_path/'jobs'
    reader = Reader(series)
    owner = ManagedNovelJobs(root, PinnedNovelSource(reader, {}))
    original_fsync = novel_storage._fsync_dir
    uncertain = []
    def fsync(path):
        if path == owner.store.root/'outputs' and not uncertain:
            uncertain.append(True)
            raise OSError('synthetic post-rename durability failure')
        original_fsync(path)
    monkeypatch.setattr(novel_storage, '_fsync_dir', fsync)
    try:
        for fmt in ('TXT','EPUB','BOTH'):
            intent = NovelJobIntent('123','91',fmt)
            wait(owner, owner.enqueue(intent, fmt).job_id, 'done')
        assert uncertain
        if series:
            intent = NovelJobIntent('123','91','BOTH',chapter_ids=('123','124'),series_title='連作')
            wait(owner, owner.enqueue(intent, 'series').job_id, 'done')
        old = owner.current('123','BOTH')
        with pytest.raises(ManagedNovelError):
            owner.enqueue(NovelJobIntent('123','91','BOTH'), 'unacknowledged')
        update = NovelJobIntent('123','91','BOTH',old.relative_receipt,old.receipt_sha256)
        job = owner.enqueue(update,'replace')
        wait(owner, job.job_id, 'done')
        assert owner.enqueue(update,'replace').job_id == job.job_id
        assert owner.current('123','BOTH').relative_receipt != old.relative_receipt
        with pytest.raises(ManagedNovelError):
            owner.enqueue(update,'stale-predecessor')
        before = owner.saved_entries()
        assert len(before) == (4 if series else 3)
        assert owner.store.reconcile(old.relative_receipt, expected_sha256=old.receipt_sha256).saved == old
    finally:
        owner.close()
    fresh = Reader(series)
    owner = ManagedNovelJobs(root, PinnedNovelSource(fresh, {}))
    try:
        assert owner.saved_entries() == before
        assert fresh.requests == []
    finally:
        owner.close()